import type { Request, Response } from 'express';
// @ts-ignore -- Generated by pnpm build; local TS and JSON imports are bundled.
import app from '../build/api-app.mjs';

/** Product metadata uses the current catalog; generated client assets stay static. */
export default function productPage(req: Request, res: Response) {
  // A standalone Vercel function receives a native response before Express runs.
  if (!['GET', 'HEAD'].includes(req.method || 'GET')) {
    res.setHeader('Allow', 'GET, HEAD');
    res.setHeader('Content-Type', 'application/json; charset=utf-8');
    res.statusCode = 405;
    res.end(JSON.stringify({ success: false, message: 'Method not allowed.' }));
    return;
  }
  let slug: unknown = req.query?.slug;
  if (slug === undefined) {
    const values = new URL(req.url || '/', 'http://localhost').searchParams.getAll('slug');
    slug = values.length === 1 ? values[0] : undefined;
  }
  if (typeof slug !== 'string' || !/^[A-Za-z0-9_-]{1,121}$/.test(slug)) {
    res.setHeader('X-Robots-Tag', 'noindex');
    res.setHeader('Content-Type', 'text/plain; charset=utf-8');
    res.statusCode = 404;
    res.end('Product not found.');
    return;
  }
  res.setHeader('Cache-Control', 'private, no-store');
  req.url = `/product/${encodeURIComponent(slug)}`;
  app(req, res);
}
